mapper.update:
UPDATE event_place_images
SET sort_order = #{sortOrder}, image_type = #{imageType}
WHERE place_id = #{placeId} AND id = #{id}

mapper.select:
SELECT id, public_id AS publicId
FROM places
WHERE public_id = #{publicId}

SELECT id, image_key, sort_order FROM oripa_place_images
WHERE place_id = #{placeId}
ORDER BY sort_order ASC, id ASC

SELECT place_id, event_type, start_date, end_date, event_hours, benefits, notice,
       summary, introduction, social_links
FROM event_place WHERE place_id = #{placeId}

SELECT id, image_key, sort_order, image_type FROM event_place_images
WHERE place_id = #{placeId}
ORDER BY FIELD(image_type, 'COVER', 'CONTENT'), sort_order ASC, id ASC
